from wtforms.fields import PasswordField, StringField
from wtforms.fields.simple import HiddenField
from wtforms.validators import InputRequired

from rdiffweb.controller import Controller, flash
from rdiffweb.controller.cherrypy_wtf import CherryForm


class LoginForm(CherryForm):
    username = StringField('Username', validators=[InputRequired()])
    password = PasswordField('Password', validators=[InputRequired()])
    hidden = HiddenField()

    def validate(self):
        if not super(LoginForm, self).validate():
            return False
        if self.username.data == 'admin' and self.password.data == 'admin':
            flash('You are logged in as admin')
            return True
        flash('Invalid username or password')
        return False


class LoginController(Controller):
    def index(self):
        form = LoginForm(self.request.forms)
        if form.validate():
            return 'You are logged in as %s' % form.username.data
        return form.render()


cherrypy.quickstart(LoginController(), '/', config={
